import Foundation
import NIO
import NIOHTTP1

// Container Orchestration - Tenant Auth Proxy
// Handles NTLM authentication relay between tenant containers and AD

struct TenantContext {
    let tenantId: String
    let isolationLevel: IsolationLevel
    let authEndpoint: URL
    let allowedDelegation: Bool
}

enum IsolationLevel: Int {
    case strict = 3
    case standard = 2
    case legacy = 1
}

class NTLMAuthHandler: ChannelInboundHandler {
    typealias InboundIn = HTTPServerRequestPart
    typealias OutboundOut = HTTPServerResponsePart

    private let tenantRegistry: TenantRegistry
    private var pendingNegotiations: [String: NTLMNegotiationState] = [:]

    init(registry: TenantRegistry) {
        self.tenantRegistry = registry
    }

    func channelRead(context: ChannelHandlerContext, data: NIOAny) {
        let reqPart = unwrapInboundIn(data)
        guard case .head(let head) = reqPart else { return }

        guard let tenantId = head.headers.first(name: "X-Tenant-ID"),
              let tenant = tenantRegistry.resolve(tenantId: tenantId) else {
            sendError(context: context, status: .forbidden)
            return
        }

        if let authHeader = head.headers.first(name: "Authorization") {
            handleNTLMAuth(context: context, authHeader: authHeader, tenant: tenant, uri: head.uri)
        } else {
            sendChallenge(context: context, tenant: tenant)
        }
    }

    private func handleNTLMAuth(context: ChannelHandlerContext, authHeader: String, tenant: TenantContext, uri: String) {
        guard authHeader.hasPrefix("NTLM ") else {
            sendError(context: context, status: .badRequest)
            return
        }

        let tokenB64 = String(authHeader.dropFirst(5))
        guard let tokenData = Data(base64Encoded: tokenB64) else {
            sendError(context: context, status: .badRequest)
            return
        }

        let messageType = extractNTLMMessageType(tokenData)

        switch messageType {
        case 1: // NEGOTIATE
            handleNegotiate(context: context, token: tokenData, tenant: tenant)
        case 3: // AUTHENTICATE
            handleAuthenticate(context: context, token: tokenData, tenant: tenant, uri: uri)
        default:
            sendError(context: context, status: .badRequest)
        }
    }

    private func handleNegotiate(context: ChannelHandlerContext, token: Data, tenant: TenantContext) {
        let sessionId = UUID().uuidString
        let state = NTLMNegotiationState(tenant: tenant, negotiateMessage: token)
        pendingNegotiations[sessionId] = state

        // Forward negotiate to tenant's AD endpoint
        let challenge = relayNegotiateToAD(token: token, endpoint: tenant.authEndpoint, tenant: tenant)

        var headers = HTTPHeaders()
        headers.add(name: "WWW-Authenticate", value: "NTLM \(challenge.base64EncodedString())")
        headers.add(name: "X-Auth-Session", value: sessionId)

        let head = HTTPResponseHead(version: .http1_1, status: .unauthorized, headers: headers)
        context.write(wrapOutboundOut(.head(head)), promise: nil)
        context.writeAndFlush(wrapOutboundOut(.end(nil)), promise: nil)
    }

    private func handleAuthenticate(context: ChannelHandlerContext, token: Data, tenant: TenantContext, uri: String) {
        // Validate authentication locally - NO relay of credentials
        let isValid = validateAuthenticateLocally(token: token, tenant: tenant, targetUri: uri)

        if isValid {
            let username = extractUsername(from: token)
            sendSuccess(context: context, user: username)
        } else {
            sendError(context: context, status: .unauthorized)
        }
    }

    /// Validates NTLM Type 3 message locally without relaying credentials
    /// Security: Never relay raw NTLM credentials across service boundaries
    private func validateAuthenticateLocally(token: Data, tenant: TenantContext, targetUri: String) -> Bool {
        let flags = extractNTLMFlags(token)
        let requestsDelegation = (flags & 0x00000004) != 0 // NTLMSSP_NEGOTIATE_SIGN

        // Check if the authentication target matches tenant boundary
        let targetInTenantScope = isTargetInScope(uri: targetUri, tenant: tenant)

        // Strict policy: never relay, always validate locally
        guard targetInTenantScope else {
            return false
        }

        // Block any delegation attempts regardless of tenant level
        if requestsDelegation {
            return false
        }

        // Validate the NTLMv2 response against locally cached challenge
        return verifyNTLMv2Response(token: token, tenant: tenant)
    }

    private func verifyNTLMv2Response(token: Data, tenant: TenantContext) -> Bool {
        // Verify the NTLM response using the tenant's local credential store
        // This does NOT relay the token - it validates cryptographically
        let verifier = LocalNTLMVerifier(tenant: tenant)
        return verifier.verify(authenticateMessage: token)
    }

    private func relayNegotiateToAD(token: Data, endpoint: URL, tenant: TenantContext) -> Data {
        // Only Type 1 (negotiate) is relayed to get the challenge
        // Type 3 (authenticate) is NEVER relayed
        var connection = ADConnection(endpoint: endpoint)
        connection.tenantIsolation = true // Always enforce isolation
        return connection.sendNegotiate(token)
    }

    private func isTargetInScope(uri: String, tenant: TenantContext) -> Bool {
        // Verify the target service is within the tenant's namespace
        // Note: /internal/ paths are NOT allowed - strict tenant scoping only
        let tenantPrefix = "/api/v1/tenants/\(tenant.tenantId)/"
        return uri.hasPrefix(tenantPrefix)
    }

    // Safe little-endian UInt32 read at a logical offset within Data.
    // Avoids unaligned load() UB/crash and respects Data.startIndex.
    private func readUInt32LE(_ data: Data, at offset: Int) -> UInt32? {
        guard offset >= 0, data.count >= offset + 4 else { return nil }
        let base = data.startIndex + offset
        let b0 = UInt32(data[base])
        let b1 = UInt32(data[base + 1])
        let b2 = UInt32(data[base + 2])
        let b3 = UInt32(data[base + 3])
        return b0 | (b1 << 8) | (b2 << 16) | (b3 << 24)
    }

    private func extractNTLMMessageType(_ data: Data) -> UInt32 {
        return readUInt32LE(data, at: 8) ?? 0
    }

    private func extractNTLMFlags(_ data: Data) -> UInt32 {
        return readUInt32LE(data, at: 12) ?? 0
    }

    private func extractUsername(from token: Data) -> String {
        // Extract username from Type 3 message domain\user fields
        guard token.count >= 36 else { return "unknown" }
        // Simplified extraction - production would parse NTLM structure
        return "authenticated_user"
    }

    private func sendChallenge(context: ChannelHandlerContext, tenant: TenantContext) {
        var headers = HTTPHeaders()
        headers.add(name: "WWW-Authenticate", value: "NTLM")
        let head = HTTPResponseHead(version: .http1_1, status: .unauthorized, headers: headers)
        context.write(wrapOutboundOut(.head(head)), promise: nil)
        context.writeAndFlush(wrapOutboundOut(.end(nil)), promise: nil)
    }

    private func sendError(context: ChannelHandlerContext, status: HTTPResponseStatus) {
        let head = HTTPResponseHead(version: .http1_1, status: status)
        context.write(wrapOutboundOut(.head(head)), promise: nil)
        context.writeAndFlush(wrapOutboundOut(.end(nil)), promise: nil)
    }

    private func sendSuccess(context: ChannelHandlerContext, user: String) {
        var headers = HTTPHeaders()
        headers.add(name: "X-Authenticated-User", value: user)
        let head = HTTPResponseHead(version: .http1_1, status: .ok, headers: headers)
        context.write(wrapOutboundOut(.head(head)), promise: nil)
        context.writeAndFlush(wrapOutboundOut(.end(nil)), promise: nil)
    }
}

struct NTLMNegotiationState {
    let tenant: TenantContext
    let negotiateMessage: Data
    let timestamp: Date = Date()
}

struct AuthResult {
    let authenticated: Bool
    let username: String
}

class ADConnection {
    let endpoint: URL
    var tenantIsolation: Bool = true

    init(endpoint: URL) {
        self.endpoint = endpoint
    }

    func sendNegotiate(_ token: Data) -> Data {
        // Stub: relay Type 1 to AD and return Type 2 challenge
        return Data()
    }
}

class LocalNTLMVerifier {
    let tenant: TenantContext

    init(tenant: TenantContext) {
        self.tenant = tenant
    }

    func verify(authenticateMessage: Data) -> Bool {
        // Cryptographic verification of NTLMv2 response
        // Uses tenant's local credential cache, no relay
        return false // Fail-closed by default
    }
}

class TenantRegistry {
    private var tenants: [String: TenantContext] = [:]

    func resolve(tenantId: String) -> TenantContext? {
        return tenants[tenantId]
    }

    func register(_ tenant: TenantContext) {
        tenants[tenant.tenantId] = tenant
    }
}
